</style>
<small>shape: (4, 5)</small><table border="1" class="dataframe"><thead><tr><th>study</th><th>eval_sum</th><th>agg_sum</th><th>agg_n_big</th><th>agg_big</th></tr><tr><td>str</td><td>list[i64]</td><td>i64</td><td>u32</td><td>list[i64]</td></tr></thead><tbody><tr><td>&quot;CT-1&quot;</td><td>[36]</td><td>36</td><td>2</td><td>[12, 15]</td></tr><tr><td>&quot;CT-2&quot;</td><td>[7]</td><td>7</td><td>0</td><td>[]</td></tr><tr><td>&quot;CT-3&quot;</td><td>[0]</td><td>0</td><td>0</td><td>[]</td></tr><tr><td>&quot;CT-4&quot;</td><td>null</td><td>null</td><td>null</td><td>null</td></tr></tbody></table></div>
```
